// Perft regression values.
//
// Every number here was cross-checked against Fairy-Stockfish 14.0.1
// (an independent implementation) and reconciled exactly - see
// docs/verification.md for the method and for why the two engines
// diverge past ply 6 from the start position.

#include <string>

#include "../core/movegen.h"
#include "test.h"

using namespace pioneer;

namespace {

Position from(const std::string& sfen) {
    Position pos;
    CHECK(pos.set(sfen));
    return pos;
}

// Pawn drops that would deliver mate: illegal for us, generated by
// Fairy-Stockfish, and therefore the entire difference between the two
// engines' node counts.
uint64_t uchifuzume_at_ply(const Position& pos, int plies_left) {
    if (plies_left == 0) {
        MoveList pseudo;
        generate_pseudo_legal(pos, pseudo);
        const Color us = pos.side_to_move();
        uint64_t n = 0;
        for (Move m : pseudo) {
            if (!is_drop(m) || drop_type(m) != PAWN) continue;
            Position next = pos;
            next.apply(m);
            if (next.attackers_to(next.king_square(us), ~us)) continue;
            if (is_checkmate(next)) ++n;
        }
        return n;
    }

    MoveList moves;
    generate_legal(pos, moves);
    uint64_t n = 0;
    for (Move m : moves) {
        Position next = pos;
        next.apply(m);
        n += uchifuzume_at_ply(next, plies_left - 1);
    }
    return n;
}

}  // namespace

TEST(perft_start_position) {
    Position pos;
    CHECK_EQ(perft(pos, 1), 14ull);
    CHECK_EQ(perft(pos, 2), 181ull);
    CHECK_EQ(perft(pos, 3), 2512ull);
    CHECK_EQ(perft(pos, 4), 35401ull);
    CHECK_EQ(perft(pos, 5), 533203ull);
    CHECK_EQ(perft(pos, 6), 8276188ull);
}

TEST(perft_positions_with_pieces_in_hand) {
    // Drops dominate the branching factor here, so these cover the
    // parts of generation the opening does not reach.
    CHECK_EQ(perft(from("4k/5/5/5/K4 b RBGSP 1"), 5), 9635599ull);
    CHECK_EQ(perft(from("4k/5/P4/5/K4 b P 1"), 5), 21958ull);
    CHECK_EQ(perft(from("3pk/5/4G/5/K4 b PG 1"), 5), 132377ull);
    CHECK_EQ(perft(from("1rsgk/4p/5/P4/KGSBR b b 3"), 5), 1131092ull);
    CHECK_EQ(perft(from("r1sgk/1b2p/5/P2R1/KGS2 b - 3"), 5), 349480ull);
}

TEST(perft_is_color_symmetric) {
    // Bare kings with all pieces in hand: same tree, opposite side to move.
    CHECK_EQ(perft(from("4k/5/5/5/K4 b RBGSP 1"), 5),
             perft(from("4k/5/5/5/K4 w rbgsp 1"), 5));
}

TEST(uchifuzume_accounts_for_the_whole_fairy_stockfish_gap) {
    // Fairy-Stockfish reports 8276188 at depth 6 (equal) and 132680698
    // at depth 7, where we report 132680617. A pawn-drop mate played
    // before the last ply leaves a mated position with no successors,
    // so it adds no leaves; the gap is exactly the drops available at
    // the final ply.
    Position pos;
    CHECK_EQ(uchifuzume_at_ply(pos, 5), 0ull);
    CHECK_EQ(uchifuzume_at_ply(pos, 6), 81ull);
    CHECK_EQ(perft(pos, 6) + uchifuzume_at_ply(pos, 5), 8276188ull);

    // Same reconciliation on a drop-heavy position: 9635599 + 148.
    Position hands = from("4k/5/5/5/K4 b RBGSP 1");
    CHECK_EQ(uchifuzume_at_ply(hands, 4), 148ull);
    CHECK_EQ(perft(hands, 5) + uchifuzume_at_ply(hands, 4), 9635747ull);
}
